const isTriggerFailure = Boolean($json.trigger);
const workflowName = $json.workflow?.name || 'Reya workflow';
const failedNode = isTriggerFailure
  ? ($json.trigger?.error?.node?.name || 'the trigger')
  : ($json.execution?.lastNodeExecuted || 'an unknown node');
const errorMessage = isTriggerFailure
  ? ($json.trigger?.error?.message || 'Unknown trigger error')
  : ($json.execution?.error?.message || 'Unknown error');
const executionUrl = $json.execution?.url || '';
const text = '⚠️ ' + workflowName + ' failed\n\n'
  + 'Stopped at: ' + failedNode + '\n'
  + 'Error: ' + errorMessage
  + (executionUrl ? '\n\nDetails: ' + executionUrl : '');
return [{json:{text}}];

const allRows = $input.all();
if (allRows.length === 0) throw new Error('The products sheet returned no rows.');

function cleanHeader(h) { return String(h).toLowerCase().replace(/[^a-z]/g, ''); }

const keys = Object.keys(allRows[0].json);
const productKey = keys.find(k => cleanHeader(k) === 'product');
const pictureKey = keys.find(k => cleanHeader(k) === 'picture');
const lastPostedKey = keys.find(k => cleanHeader(k) === 'lastposted');
if (!productKey) throw new Error('Product column was not found.');
if (!pictureKey) throw new Error('Picture column was not found. Columns received: ' + keys.join(', '));

const seenPictures = new Set();
const usableRows = [];
for (const item of allRows) {
  const product = String(item.json[productKey] ?? '').trim();
  const picture = String(item.json[pictureKey] ?? '').trim();
  if (!product || !picture) continue;
  if (product.toLowerCase() === 'in production') continue;
  if (seenPictures.has(picture)) continue;
  seenPictures.add(picture);
  usableRows.push(item.json);
}
if (usableRows.length === 0) throw new Error('All product rows have an empty Product or Picture, or were excluded.');

// Google Sheets may hand back the date as text (ISO) OR as a sheet serial
// number (days since 1899-12-30). Handle both so the sort is always right.
function lastPostedTime(row) {
  if (!lastPostedKey) return 0;
  const raw = row[lastPostedKey];
  if (raw === undefined || raw === null || raw === '') return 0;
  if (typeof raw === 'number' || /^\d+(\.\d+)?$/.test(String(raw))) {
    return (Number(raw) - 25569) * 86400000;
  }
  const t = Date.parse(raw);
  return Number.isNaN(t) ? 0 : t;
}

// Oldest (or never) posted first; row order breaks ties.
usableRows.sort((a, b) => lastPostedTime(a) - lastPostedTime(b));
const chosen = usableRows[0];

// Keep the EXACT sheet value so the Last Posted update matches the row.
const sheetProductName = String(chosen[productKey]);
const pictureLink = String(chosen[pictureKey]).trim();
const driveMatch = pictureLink.match(/\/file\/d\/([^\/]+)/) || pictureLink.match(/[?&]id=([^&]+)/);
const driveFileId = driveMatch ? driveMatch[1] : '';
const imageUrl = driveFileId ? `https://drive.google.com/thumbnail?id=${driveFileId}&sz=w1600` : pictureLink;

return [{ json: {
  product: { ...chosen, Product: sheetProductName.trim(), SheetProductName: sheetProductName, Picture: imageUrl, DriveFileId: driveFileId },
  regeneration: false,
}}];

// Read from Pick One Product so this works regardless of what the
// Sheets update node returns.
const p = $('Pick One Product').first().json;
return [{json:{product: p.product, regeneration: Boolean(p.regeneration)}}];

let raw = $json.output || $json.text || '';
raw = String(raw).trim().replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/```$/,'');
const ai = JSON.parse(raw);
const source = $('Prepare Product for AI').item.json.product;
const hashtags = Array.isArray(ai.hashtags) ? ai.hashtags.join(' ') : String(ai.hashtags || '');
const draftId = Date.now().toString(36) + Math.random().toString(36).slice(2,7);
return [{json:{draftId,product:String(source.Product || ai.product || ''),caption:String(ai.caption || ''),hashtags,imageUrl:String(source.Picture || ''),driveFileId:String(source.DriveFileId || ''),price:String(source.Price || ''),weight:String(source.weight || ''),status:'PENDING_APPROVAL'}}];

const store = $getWorkflowStaticData('global');
store.contentDrafts = store.contentDrafts || {};
store.processedMessages = store.processedMessages || {};

// Only one draft may be waiting at a time. Anything still pending when a
// new picture goes out is closed as auto-denied by the sweep; here we just
// record when this draft was sent so the 6h window can be enforced.
store.contentDrafts[$json.draftId] = { ...$json, createdAt: Date.now(), status: 'PENDING_APPROVAL' };

// Housekeeping: forget drafts/claims older than 7 days.
const cutoff = Date.now() - 7 * 24 * 3600 * 1000;
for (const [id, d] of Object.entries(store.contentDrafts)) {
  if ((d.createdAt || 0) < cutoff) { delete store.contentDrafts[id]; delete store.processedMessages[id]; }
}
return $input.all();

const cb = $json.callback_query;
if (!cb) return [];

const AUTHORIZED_USER_IDS = new Set(['8469419204', '1798976243']);
if (!AUTHORIZED_USER_IDS.has(String(cb.from?.id))) throw new Error('Unauthorized Telegram approval user.');
const actorName = cb.from?.first_name || 'Someone';

const parts = String(cb.data || '').split(':');
const action = parts[0];
const payload = parts[1];
const draftKey = parts[2] || payload;
const isDriveId = /^[A-Za-z0-9_-]{15,}$/.test(payload || '');

// 6-hour approval window from the original send time.
const APPROVAL_WINDOW_MS = 6 * 60 * 60 * 1000;
const sentAtMs = (cb.message?.date || 0) * 1000;
const expired = sentAtMs > 0 && (Date.now() - sentAtMs) > APPROVAL_WINDOW_MS;

// Read-only check of the claim (the write happens in Claim Message).
// The auto-deny sweep also writes here, so a late tap after auto-deny
// is reported as already handled.
const store = $getWorkflowStaticData('global');
store.processedMessages = store.processedMessages || {};
const messageKey = String(cb.message.chat.id) + ':' + String(cb.message.message_id);
const priorClaim = store.processedMessages[draftKey];
const alreadyProcessed = Boolean(priorClaim);

const captionText = String(cb.message?.caption || '');
const firstBreak = captionText.indexOf('\n\n');
const lastBreak = captionText.lastIndexOf('\n\n');
const draft = store.contentDrafts?.[draftKey];
const product = draft?.product || (firstBreak === -1 ? captionText : captionText.slice(0, firstBreak)).replace(/^\u{1F56F}\uFE0F?\s*/u, '').trim();
const caption = draft?.caption || (firstBreak !== -1 && firstBreak !== lastBreak ? captionText.slice(firstBreak + 2, lastBreak).trim() : '');
const hashtags = draft?.hashtags || (lastBreak !== -1 ? captionText.slice(lastBreak + 2).trim() : '');

// Resolve the picture for BOTH approve and decline so the sheet log
// always records which picture it was.
let imageUrl = draft?.imageUrl || (isDriveId ? `https://drive.google.com/thumbnail?id=${payload}&sz=w1600` : '');
if (action === 'approve' && !expired && !alreadyProcessed && !imageUrl) {
  throw new Error('Could not recover the image for this post (draft ' + draftKey + ' not found).');
}

return [{json:{
  action, actorName, product, caption, hashtags, imageUrl,
  callbackQueryId: cb.id,
  chatId: cb.message.chat.id,
  messageId: cb.message.message_id,
  messageKey, draftKey, alreadyProcessed,
  resolvedAction: priorClaim?.action,
  resolvedBy: priorClaim?.by,
  expired
}}];

const store = $getWorkflowStaticData('global');
store.processedMessages = store.processedMessages || {};
store.contentDrafts = store.contentDrafts || {};
const decision = $('Load Approval Decision').item.json;

// Re-check at claim time (the sweep may have run in between).
if (store.processedMessages[decision.draftKey]) return [];

if (decision.expired) {
  // Late tap on an expired draft that the sweep hasn't closed yet:
  // close it here as auto-denied so it's still logged exactly once.
  store.processedMessages[decision.draftKey] = { action: 'reject', by: 'Auto (no reply in 6h)' };
  if (store.contentDrafts[decision.draftKey]) store.contentDrafts[decision.draftKey].status = 'AUTO_DENIED';
  return [{ json: { ...decision, action: 'reject', actorName: 'Auto (no reply in 6h)' } }];
}

store.processedMessages[decision.draftKey] = { action: decision.action, by: decision.actorName };
if (store.contentDrafts[decision.draftKey]) store.contentDrafts[decision.draftKey].status = decision.action === 'approve' ? 'APPROVED' : 'DENIED';
return [{ json: decision }];

const d = $json;
const parts = new Intl.DateTimeFormat('en-GB', {timeZone: 'Asia/Amman', year:'numeric', month:'2-digit', day:'2-digit', hour:'2-digit', minute:'2-digit', hour12:false}).formatToParts(new Date());
const get = t => parts.find(p => p.type === t).value;
return [{json:{
  'Date': get('year') + '-' + get('month') + '-' + get('day'),
  'Time (hh:mm)': get('hour') + ':' + get('minute'),
  'Approved Ad Picture': d.imageUrl || '',
  'Denied Ad Picture': '',
  'By (Reda/Yanal)': d.actorName || ''
}}];

const d = $json;
const parts = new Intl.DateTimeFormat('en-GB', {timeZone: 'Asia/Amman', year:'numeric', month:'2-digit', day:'2-digit', hour:'2-digit', minute:'2-digit', hour12:false}).formatToParts(new Date());
const get = t => parts.find(p => p.type === t).value;
return $input.all().map(i => ({json:{
  'Date': get('year') + '-' + get('month') + '-' + get('day'),
  'Time (hh:mm)': get('hour') + ':' + get('minute'),
  'Approved Ad Picture': '',
  'Denied Ad Picture': i.json.imageUrl || '',
  'By (Reda/Yanal)': i.json.actorName || ''
}}));

// Auto-deny any draft that got no Approve/Decline within 6 hours.
// Change APPROVAL_WINDOW_HOURS to 4 if you prefer a 4-hour window
// (also change the 6 in Load Approval Decision).
const APPROVAL_WINDOW_HOURS = 6;
const store = $getWorkflowStaticData('global');
store.contentDrafts = store.contentDrafts || {};
store.processedMessages = store.processedMessages || {};
const now = Date.now();
const out = [];
for (const [id, d] of Object.entries(store.contentDrafts)) {
  if (store.processedMessages[id]) continue;
  if (!d.createdAt || now - d.createdAt < APPROVAL_WINDOW_HOURS * 3600 * 1000) continue;
  const by = 'Auto (no reply in ' + APPROVAL_WINDOW_HOURS + 'h)';
  store.processedMessages[id] = { action: 'reject', by };
  d.status = 'AUTO_DENIED';
  out.push({ json: { draftKey: id, product: d.product, imageUrl: d.imageUrl, actorName: by, action: 'reject' } });
}
return out;
